import React, { useEffect, useRef } from 'react';

const technologies = [
  {
    name: 'React.js',
    category: 'Frontend',
    icon: (
      <svg viewBox="0 0 24 24" className="w-12 h-12" fill="none" stroke="currentColor" strokeWidth="1.5">
        <circle cx="12" cy="12" r="2" fill="currentColor" stroke="none"/>
        <ellipse cx="12" cy="12" rx="9" ry="4" transform="rotate(0 12 12)"/>
        <ellipse cx="12" cy="12" rx="9" ry="4" transform="rotate(60 12 12)"/>
        <ellipse cx="12" cy="12" rx="9" ry="4" transform="rotate(120 12 12)"/>
      </svg>
    ),
    color: '#61DAFB'
  },
  {
    name: 'Tailwind CSS',
    category: 'Styling',
    icon: (
      <svg viewBox="0 0 24 24" className="w-12 h-12" fill="currentColor">
        <path d="M12.001,4.8c-3.2,0-5.2,1.6-6,4.8c1.2-1.6,2.6-2.2,4.2-1.8c0.913,0.228,1.565,0.89,2.288,1.624 C13.666,10.618,15.027,12,18.001,12c3.2,0,5.2-1.6,6-4.8c-1.2,1.6-2.6,2.2-4.2,1.8c-0.913-0.228-1.565-0.89-2.288-1.624 C16.337,6.182,14.976,4.8,12.001,4.8z M6.001,12c-3.2,0-5.2,1.6-6,4.8c1.2-1.6,2.6-2.2,4.2-1.8c0.913,0.228,1.565,0.89,2.288,1.624 c1.177,1.194,2.538,2.576,5.512,2.576c3.2,0,5.2-1.6,6-4.8c-1.2,1.6-2.6,2.2-4.2,1.8c-0.913-0.228-1.565-0.89-2.288-1.624 C10.337,13.382,8.976,12,6.001,12z"/>
      </svg>
    ),
    color: '#38BDF8'
  },
  {
    name: 'JavaScript',
    category: 'Language',
    icon: (
      <svg viewBox="0 0 24 24" className="w-12 h-12" fill="none">
        <rect width="24" height="24" rx="4" fill="#F7DF1E"/>
        <path d="M18.5 19l-2-12h3l1.5 7.5L22.5 7h3l-5 12h-2z" fill="#000"/>
        <path d="M6 7h9v2.5H8.5v3H13v2.5H8.5V18H6V7z" fill="#000"/>
      </svg>
    ),
    color: '#F7DF1E'
  },
  {
    name: 'PHP',
    category: 'Backend',
    icon: (
      <svg viewBox="0 0 24 24" className="w-12 h-12" fill="none">
        <ellipse cx="12" cy="12" rx="10" ry="6" fill="#777BB4"/>
        <text x="12" y="14" textAnchor="middle" fill="white" fontSize="8" fontWeight="bold">php</text>
      </svg>
    ),
    color: '#777BB4'
  },
  {
    name: 'MySQL',
    category: 'Database',
    icon: (
      <svg viewBox="0 0 24 24" className="w-12 h-12" fill="none">
        <path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2z" fill="#4479A1"/>
        <text x="12" y="15" textAnchor="middle" fill="white" fontSize="6" fontWeight="bold">SQL</text>
      </svg>
    ),
    color: '#4479A1'
  },
  {
    name: 'Node.js',
    category: 'Backend',
    icon: (
      <svg viewBox="0 0 24 24" className="w-12 h-12" fill="#339933">
        <path d="M12 2L3 7v10l9 5 9-5V7l-9-5zm0 2.5L18.5 8 12 11.5 5.5 8 12 4.5zM5 9.5l6 3.5v6.5l-6-3.5V9.5zm14 0v6.5l-6 3.5v-6.5l6-3.5z"/>
      </svg>
    ),
    color: '#339933'
  },
  {
    name: 'Git',
    category: 'Tools',
